315→// mergeRedaction merges redaction overrides into existing RedactionSettings.
316→// Only fields present in the override JSON are applied.
317→func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
318→	var raw map[string]json.RawMessage
319→	if err := json.Unmarshal(data, &raw); err != nil {
320→		return fmt.Errorf("parsing redaction: %w", err)
321→	}
322→	if piiRaw, ok := raw["pii"]; ok {
323→		if dst.PII == nil {
324→			dst.PII = &PIISettings{}
325→		}
326→		if err := mergePIISettings(dst.PII, piiRaw); err != nil {
327→			return err
328→		}
329→	}
330→	return nil
331→}
332→
333→// mergePIISettings merges PII overrides into existing PIISettings.
334→// Only fields present in the override JSON are applied; missing fields
335→// are preserved from the base settings.
336→func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
337→	var raw map[string]json.RawMessage
338→	if err := json.Unmarshal(data, &raw); err != nil {
339→		return fmt.Errorf("parsing pii: %w", err)
340→	}
341→	if v, ok := raw["enabled"]; ok {
342→		if err := json.Unmarshal(v, &dst.Enabled); err != nil {
343→			return fmt.Errorf("parsing pii.enabled: %w", err)
344→		}
345→	}
346→	if v, ok := raw["email"]; ok {
347→		var b bool
348→		if err := json.Unmarshal(v, &b); err != nil {
349→			return fmt.Errorf("parsing pii.email: %w", err)
350→		}
351→		dst.Email = &b
352→	}
353→	if v, ok := raw["phone"]; ok {
354→		var b bool
355→		if err := json.Unmarshal(v, &b); err != nil {
356→			return fmt.Errorf("parsing pii.phone: %w", err)
357→		}
358→		dst.Phone = &b
359→	}
360→	if v, ok := raw["address"]; ok {
361→		var b bool
362→		if err := json.Unmarshal(v, &b); err != nil {
363→			return fmt.Errorf("parsing pii.address: %w", err)
364→		}
365→		dst.Address = &b
366→	}
367→	if v, ok := raw["custom_patterns"]; ok {
368→		var cp map[string]string
369→		if err := json.Unmarshal(v, &cp); err != nil {
370→			return fmt.Errorf("parsing pii.custom_patterns: %w", err)
371→		}
372→		if dst.CustomPatterns == nil {
373→			dst.CustomPatterns = cp
374→		} else {
375→			for k, val := range cp {
376→				dst.CustomPatterns[k] = val
377→			}
378→		}
379→	}
380→	return nil
381→}
