	t.Parallel()
	f := Filter{Match: "/home/user/project", Replace: "__ent__/repo"}
	got := f.Smudge([]byte("file at __ent__/repo/src/main.go"))
	want := "file at /home/user/project/src/main.go"
	if string(got) != want {
		t.Errorf("Smudge() = %q, want %q", got, want)
	}
