237→// WriteTemporaryTask writes a task checkpoint to a shadow branch.
238→// Task checkpoints include both code changes and task-specific metadata.
239→// Returns the commit hash of the created checkpoint.
240→func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
241→	// Validate base commit - required for shadow branch naming
242→	if opts.BaseCommit == "" {
243→		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
244→	}
245→
246→	// Validate identifiers to prevent path traversal and malformed data
247→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
248→		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
249→	}
250→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
251→		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
252→	}
253→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
254→		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
255→	}
256→
257→	// Get shadow branch name
258→	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit, opts.WorktreeID)
259→
260→	// Get or create shadow branch
261→	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
262→	if err != nil {
263→		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
264→	}
265→
266→	// Collect all files to include in the commit
267→	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
268→	allFiles = append(allFiles, opts.ModifiedFiles...)
269→	allFiles = append(allFiles, opts.NewFiles...)
270→
271→	// Build new tree with code changes (no metadata dir yet; nil pipeline — task checkpoints have no metadata dir)
272→	newTreeHash, err := s.buildTreeWithChanges(ctx, baseTreeHash, allFiles, opts.DeletedFiles, "", "", nil)
273→	if err != nil {
274→		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
275→	}
276→
277→	// Add task metadata to tree
278→	newTreeHash, err = s.addTaskMetadataToTree(ctx, newTreeHash, opts)
279→	if err != nil {
280→		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
281→	}
282→
283→	// Create the commit
284→	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
285→	if err != nil {
286→		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
287→	}
288→
289→	// Update shadow branch reference
290→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
291→	ref := plumbing.NewHashReference(refName, commitHash)
292→	if err := s.repo.Storer.SetReference(ref); err != nil {
293→		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
294→	}
295→
296→	return commitHash, nil
297→}

1558→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
1559→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
1560→// The agentType is used for reassembling chunks in the correct format.
1561→func readTranscriptFromTree(ctx context.Context, tree *FetchingTree, agentType types.AgentType) ([]byte, error) {
1562→	// Collect all transcript-related files
1563→	var chunkFiles []string
1564→	var hasBaseFile bool
1565→
1566→	for _, entry := range tree.RawEntries() {
1567→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
1568→			hasBaseFile = true
1569→		}
1570→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
1571→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
1572→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
1573→			if idx > 0 {
1574→				chunkFiles = append(chunkFiles, entry.Name)
1575→			}
1576→		}
1577→	}
1578→
1579→	// If we have chunk files, read and reassemble them
1580→	if len(chunkFiles) > 0 {
1581→		// Sort chunk files by index
1582→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
1583→
1584→		// Check if base file should be included as chunk 0.
1585→		// NOTE: This assumes the chunking convention where the unsuffixed file
1586→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
1587→		if hasBaseFile {
1588→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
1589→		}
1590→
1591→		var chunks [][]byte
1592→		for _, chunkFile := range chunkFiles {
1593→			file, err := tree.File(chunkFile)
1594→			if err != nil {
1595→				logging.Warn(ctx, "failed to read transcript chunk file from tree",
1596→					slog.String("chunk_file", chunkFile),
1597→					slog.String("error", err.Error()),
1598→				)
1599→				continue
1600→			}
1601→			content, err := file.Contents()
1602→			if err != nil {
1603→				logging.Warn(ctx, "failed to read transcript chunk contents",
1604→					slog.String("chunk_file", chunkFile),
1605→					slog.String("error", err.Error()),
1606→				)
1607→				continue
1608→			}
1609→			chunks = append(chunks, []byte(content))
1610→		}
1611→
1612→		if len(chunks) > 0 {
1613→			result, err := agent.ReassembleTranscript(chunks, agentType)
1614→			if err != nil {
1615→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
1616→			}
1617→			return result, nil
1618→		}
1619→	}
1620→
1621→	// Fall back to reading base file (non-chunked or backwards compatibility)
1622→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
1623→		if content, err := file.Contents(); err == nil {
1624→			return []byte(content), nil
1625→		}
1626→	}
1627→
1628→	// Try legacy filename
1629→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
1630→		if content, err := file.Contents(); err == nil {
1631→			return []byte(content), nil
1632→		}
1633→	}
1634→
1635→	return nil, nil
1636→}
