636→// DeleteShadowBranch deletes the shadow branch for the given base commit and worktree.
637→// worktreeID should be empty for main worktree or the internal git worktree name for linked worktrees.
638→// Uses git CLI instead of go-git's RemoveReference because go-git v5 doesn't properly
639→// persist deletions with packed refs or worktrees.
640→func (s *GitStore) DeleteShadowBranch(ctx context.Context, baseCommit, worktreeID string) error {
641→	shadowBranchName := ShadowBranchNameForCommit(baseCommit, worktreeID)
642→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", shadowBranchName)
643→	if output, err := cmd.CombinedOutput(); err != nil {
