  2→// Transcripts stored in checkpoints contain absolute paths (repo root, home directory)
  3→// which are machine-specific. This package normalizes paths on store (clean) and
  4→// restores them on read (smudge), similar to git's clean/smudge filter pipeline.
  5→package filter
  6→
  7→import (
  8→	"bytes"
  9→	"fmt"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/settings"
 12→)
 13→
 14→// Filter defines a single find-and-replace pair used during clean/smudge.
 15→// Clean replaces Match with Replace; Smudge reverses the substitution.
 16→type Filter struct {
 17→	Match   string // literal string to find
 18→	Replace string // literal string to substitute
 19→}
 20→
 21→// Clean applies the filter in the "store" direction: Match → Replace.
 22→func (f Filter) Clean(data []byte) []byte {
 23→	return bytes.ReplaceAll(data, []byte(f.Match), []byte(f.Replace))
 24→}
 25→
 26→// Smudge applies the filter in the "restore" direction: Replace → Match.
 27→func (f Filter) Smudge(data []byte) []byte {
 28→	return bytes.ReplaceAll(data, []byte(f.Replace), []byte(f.Match))
 29→}
 30→
 31→// Pipeline holds an ordered list of filters and applies them collectively.
 32→// A nil *Pipeline is safe to use — all methods are no-ops.
 33→type Pipeline struct {
 34→	filters []Filter
 35→}
 36→
 37→// NewPipeline creates a filter pipeline with built-in path filters and optional user filters.
 38→// Built-in filters (applied first, most-specific first):
 39→//  1. repoRoot → __ent__/repo
 40→//  2. homeDir  → __ent__/home
 41→//
 42→// User filters are appended after built-ins.
 43→func NewPipeline(repoRoot, homeDir string, userFilters []settings.TranscriptFilter) (*Pipeline, error) {
 44→	var filters []Filter
 45→
 46→	// Built-in filters, most-specific first (repo root before home dir,
 47→	// since repo root is typically under home dir).
 48→	if repoRoot != "" {
 49→		f := Filter{Match: repoRoot, Replace: "__ent__/repo"}
 50→		if err := ValidateFilter(f, true); err != nil {
 51→			return nil, err
 52→		}
 53→		filters = append(filters, f)
 54→	}
 55→	if homeDir != "" {
 56→		f := Filter{Match: homeDir, Replace: "__ent__/home"}
 57→		if err := ValidateFilter(f, true); err != nil {
 58→			return nil, err
 59→		}
 60→		filters = append(filters, f)
 61→	}
 62→
 63→	// User filters
 64→	for _, uf := range userFilters {
 65→		if err := validateUserFilterKey(uf.Key); err != nil {
 66→			return nil, fmt.Errorf("invalid transcript filter key %q: %w", uf.Key, err)
 67→		}
 68→		f := Filter{
 69→			Match:   uf.Match,
 70→			Replace: "__ent_user__/" + uf.Key,
 71→		}
 72→		if err := ValidateFilter(f, false); err != nil {
 73→			return nil, err
 74→		}
 75→		filters = append(filters, f)
 76→	}
 77→
 78→	return &Pipeline{filters: filters}, nil
 79→}
 80→
 81→// Clean applies all filters in order (store direction).
 82→// Safe to call on a nil *Pipeline (returns data unchanged).
 83→func (p *Pipeline) Clean(data []byte) []byte {
 84→	if p == nil {
 85→		return data
 86→	}
 87→	for _, f := range p.filters {
 88→		data = f.Clean(data)
 89→	}
 90→	return data
 91→}
 92→
 93→// Smudge applies all filters in reverse order (restore direction).
 94→// Safe to call on a nil *Pipeline (returns data unchanged).
 95→func (p *Pipeline) Smudge(data []byte) []byte {
 96→	if p == nil {
 97→		return data
 98→	}
 99→	for i := len(p.filters) - 1; i >= 0; i-- {
100→		data = p.filters[i].Smudge(data)
101→	}
102→	return data
103→}
104→
105→// CleanString applies Clean to a string value.
106→// Safe to call on a nil *Pipeline (returns s unchanged).
107→func (p *Pipeline) CleanString(s string) string {
108→	if p == nil {
109→		return s
110→	}
111→	return string(p.Clean([]byte(s)))
112→}
113→
114→// SmudgeString applies Smudge to a string value.
115→// Safe to call on a nil *Pipeline (returns s unchanged).
116→func (p *Pipeline) SmudgeString(s string) string {
117→	if p == nil {
118→		return s
119→	}
120→	return string(p.Smudge([]byte(s)))
121→}
