263→		return fmt.Errorf("failed to read checkpoint content: %w", err)
264→	}
265→
266→	// Handle summary generation
267→	if generate {
268→		if err := generateCheckpointSummary(ctx, w, errW, store, fullCheckpointID, summary, content, force); err != nil {
269→			return err
270→		}
271→		// Reload the content to get the updated summary
272→		content, err = store.ReadLatestSessionContent(ctx, fullCheckpointID)
273→		if err != nil {
274→			return fmt.Errorf("failed to reload checkpoint: %w", err)
275→		}
276→	}
277→
278→	// Handle raw transcript output
279→	if rawTranscript {
280→		if len(content.Transcript) == 0 {
281→			return fmt.Errorf("checkpoint %s has no transcript", fullCheckpointID)
282→		}
283→		// Output raw transcript directly (no pager, no formatting)
284→		if _, err = w.Write(content.Transcript); err != nil {
285→			return fmt.Errorf("failed to write transcript: %w", err)
286→		}
287→		return nil
288→	}
289→
