307→	output := formatCheckpointOutput(summary, content, fullCheckpointID, associatedCommits, author, verbose, full)
308→	outputExplainContent(w, output, noPager)
309→	return nil

602→func formatCheckpointOutput(summary *checkpoint.CheckpointSummary, content *checkpoint.SessionContent, checkpointID id.CheckpointID, associatedCommits []associatedCommit, author checkpoint.Author, verbose, full bool) string {
603→	var sb strings.Builder
604→	meta := content.Metadata
605→
606→	// Scope the transcript to this checkpoint's portion
607→	// If CheckpointTranscriptStart > 0, we slice the transcript to only include
608→	// content from that point onwards (excluding earlier checkpoint content)
609→	scopedTranscript := scopeTranscriptForCheckpoint(content.Transcript, meta.GetTranscriptStart(), meta.Agent)
610→
611→	// Extract prompts from the scoped transcript for intent extraction
612→	scopedPrompts := extractPromptsFromTranscript(scopedTranscript, meta.Agent)
613→
614→	// Header - always shown
