639→		fmt.Fprintf(&sb, "Commits: (%d)\n", len(associatedCommits))
640→		for _, c := range associatedCommits {
641→			fmt.Fprintf(&sb, "  %s %s %s\n", c.ShortSHA, c.Date.Format("2006-01-02"), c.Message)
