643→	} else if associatedCommits != nil {
644→		// associatedCommits is non-nil but empty - show "no commits found" message
645→		sb.WriteString("\nCommits: No commits found on this branch\n")
646→	}
647→
648→	sb.WriteString("\n")
649→
650→	// Intent and Outcome from AI summary, or fallback to prompt text
651→	if meta.Summary != nil {
652→		fmt.Fprintf(&sb, "Intent: %s\n", meta.Summary.Intent)
653→		fmt.Fprintf(&sb, "Outcome: %s\n", meta.Summary.Outcome)
654→	} else {
655→		// Fallback: use first line of scoped prompts for intent,
656→		// or fall back to result.Prompts for backwards compatibility with older checkpoints
657→		intent := "(not generated)"
658→		if len(scopedPrompts) > 0 && scopedPrompts[0] != "" {
659→			intent = strategy.TruncateDescription(scopedPrompts[0], maxIntentDisplayLength)
660→		} else if content.Prompts != "" {
661→			// Backwards compatibility: use stored prompts if no transcript available
662→			lines := strings.Split(content.Prompts, "\n")
663→			if len(lines) > 0 && lines[0] != "" {
664→				intent = strategy.TruncateDescription(lines[0], maxIntentDisplayLength)
665→			}
666→		}
667→		fmt.Fprintf(&sb, "Intent: %s\n", intent)
668→		sb.WriteString("Outcome: (not generated)\n")
669→	}
670→
671→	// Verbose: add learnings, friction, files, and scoped transcript
672→	if verbose || full {
673→		// AI Summary details (learnings, friction, open items)
674→		if meta.Summary != nil {
675→			formatSummaryDetails(&sb, meta.Summary)
676→		}
677→
678→		sb.WriteString("\n")
679→
680→		// Files section
681→		if len(meta.FilesTouched) > 0 {
682→			fmt.Fprintf(&sb, "Files: (%d)\n", len(meta.FilesTouched))
683→			for _, file := range meta.FilesTouched {
684→				fmt.Fprintf(&sb, "  - %s\n", file)
685→			}
686→		} else {
687→			sb.WriteString("Files: (none)\n")
688→		}
689→	}
690→
691→	// Transcript section: full shows entire session, verbose shows checkpoint scope
692→	appendTranscriptSection(&sb, verbose, full, content.Transcript, scopedTranscript, content.Prompts, meta.Agent)
693→
694→	return sb.String()
695→}
