697→// appendTranscriptSection appends the appropriate transcript section to the builder
698→// based on verbosity level. Full mode shows the entire session, verbose shows checkpoint scope.
699→// fullTranscript is the entire session transcript, scopedContent is either scoped transcript bytes
700→// or a pre-formatted string (for backwards compat), and scopedFallback is used when scoped parsing fails.
701→func appendTranscriptSection(sb *strings.Builder, verbose, full bool, fullTranscript, scopedTranscript []byte, scopedFallback string, agentType types.AgentType) {
