667→+
668→+// ValidateFilter checks that a filter is well-formed.
669→+// isBuiltIn distinguishes built-in filters (whose replacements start with __ent__/)
670→+// from user filters (whose replacements must start with __ent_user__/).
671→+func ValidateFilter(f Filter, isBuiltIn bool) error {
672→+	if f.Match == "" {
673→+		return errors.New("filter match must be non-empty")
674→+	}
675→+	if f.Replace == "" {
676→+		return errors.New("filter replace must be non-empty")
677→+	}
678→+	if f.Match == f.Replace {
679→+		return errors.New("filter match and replace must be different")
680→+	}
681→+
682→+	// Idempotency: applying clean twice must produce the same result.
683→+	// This means the replacement string must not itself contain the match pattern,
684→+	// AND the match string must not contain the replacement pattern (which would
685→+	// cause smudge to corrupt the match).
686→+	if strings.Contains(f.Replace, f.Match) {
687→+		return fmt.Errorf("filter replace %q must not contain match %q (not idempotent)", f.Replace, f.Match)
688→+	}
689→+	if strings.Contains(f.Match, f.Replace) {
690→+		return fmt.Errorf("filter match %q must not contain replace %q (smudge would corrupt)", f.Match, f.Replace)
691→+	}
692→+
693→+	if isBuiltIn {
694→+		if !strings.HasPrefix(f.Replace, builtInPrefix) {
695→+			return fmt.Errorf("built-in filter replace must start with %q, got %q", builtInPrefix, f.Replace)
696→+		}
697→+		if len(f.Match) < minBuiltInMatchLen {
698→+			return fmt.Errorf("built-in filter match must be at least %d characters, got %d", minBuiltInMatchLen, len(f.Match))
699→+		}
700→+	} else {
701→+		if !strings.HasPrefix(f.Replace, userPrefix) {
702→+			return fmt.Errorf("user filter replace must start with %q, got %q", userPrefix, f.Replace)
703→+		}
704→+		if len(f.Match) < minUserMatchLen {
705→+			return fmt.Errorf("user filter match must be at least %d characters, got %d", minUserMatchLen, len(f.Match))
706→+		}
707→+	}
708→+
709→+	return nil
710→+}
711→+
712→+// validateUserFilterKey checks that a user-supplied filter key is safe to use
713→+// as a replacement token suffix. Rejects empty keys, keys containing path
714→+// separators, and keys that could collide with built-in marker prefixes.
715→+func validateUserFilterKey(key string) error {
716→+	if key == "" {
717→+		return errors.New("must be non-empty")
718→+	}
719→+	if strings.ContainsAny(key, "/\\") {
720→+		return errors.New("must not contain path separators")
721→+	}
722→+	if strings.HasPrefix(key, "__ent") {
723→+		return errors.New("must not start with reserved prefix \"__ent\"")
724→+	}
725→+	return nil
726→+}
