+
+func TestValidateUserFilterKey(t *testing.T) {
+	t.Parallel()
+	tests := []struct {
+		name    string
+		key     string
+		wantErr bool
+	}{
+		{name: "valid key", key: "hostname", wantErr: false},
+		{name: "empty key", key: "", wantErr: true},
